from taf.sbts.oam.coam.admin import admin

from taf.rfrl.l3_call.cell.classical_cell.classical_nr_cell import ClassicalNrCell
from taf.rfrl.l3_call.cell.classical_cell.classical_lte_cell import ClassicalLteCell
from taf.rfrl.l3_call.cell.classical_cell.classical_iot_cell import ClassicalIotCell
from taf.rfrl.l3_call.cell.classical_cell.classical_gsm_cell import ClassicalGsmCell
from taf.rfrl.l3_call.cell.classical_cell.classical_wcdma_cell import ClassicalWcdmaCell
from taf.rfrl.l3_call.cell.cloud_cell.cloud_nr_cell import CloudNrCell
from taf.rfrl.l3_call.cell.exceptions import InvalidCellType, InvalidRan


class CellFactory:
    """
    Creates CloudNrCell, ClassicalNrCell, ClassicalLteCell,
    ClassicalGsmCell or ClassicalWcdmaCell instances
    """

    @staticmethod
    def create_cell(ran, cell_distname, bts_connection_alias="l3_call_gnb", shared_spectrum=False):
        """
        Creates CloudNrCell, ClassicalNrCell, ClassicalLteCell, ClassicalIotCell, ClassicalGsmCell or
        ClassicalWcdmaCell instances depending on ran and cell_type retrieved from cell_distname

        :param ran: RAN type: classical/cloud
        :type ran: str
        :param cell_distname: distname of cell
        :type cell_distname: str
        :param bts_connection_alias: admin connection alias, by default 'l3_call_gnb'
        :type bts_connection_alias: Union(str, dict), str for Classical RAN, dict for Cloud RAN e.g.:
                                    {"DU_1": "alias_du_1", "DU_2": "alias_du_2"} default: 'l3_call_gnb'
        :param shared_spectrum: optional parameter for not called cells stating whether
        spectrum is shared between the cell and called cell
        :type shared_spectrum: bool, default: False

        :return: CloudNrCell, ClassicalNrCell, ClassicalLteCell, ClassicalIotCell,
                 ClassicalGsmCell or ClassicalWcdmaCell
        :rtype: Cell
        """
        cell_type = cell_distname.split("/")[-1]

        if ran == "classical":
            if "NRCELL" in cell_type:
                return ClassicalNrCell(cell_distname=cell_distname,
                                       shared_spectrum=shared_spectrum,
                                       bts_connection_alias=bts_connection_alias)
            if "LNCEL" in cell_type:
                if CellFactory._is_lte_iot_cell(cell_distname=cell_distname, connection=bts_connection_alias):
                    return ClassicalIotCell(cell_distname=cell_distname,
                                            shared_spectrum=shared_spectrum,
                                            bts_connection_alias=bts_connection_alias)
                else:
                    return ClassicalLteCell(cell_distname=cell_distname,
                                            shared_spectrum=shared_spectrum,
                                            bts_connection_alias=bts_connection_alias)

            if "GNCEL" in cell_type:
                return ClassicalGsmCell(cell_distname=cell_distname,
                                        shared_spectrum=shared_spectrum,
                                        bts_connection_alias=bts_connection_alias)
            if "WNCEL" in cell_type:
                return ClassicalWcdmaCell(cell_distname=cell_distname,
                                          shared_spectrum=shared_spectrum,
                                          bts_connection_alias=bts_connection_alias)
            else:
                raise InvalidCellType("Cell Type for classical RAN must be either 'NRCELL', "
                                      "'LNCEL', 'GNCEL' or 'WNCEL'!")

        elif ran == "cloud":
            if "NRCELL" in cell_type:
                return CloudNrCell(cell_distname=cell_distname, vdu_aliases=bts_connection_alias,
                                   shared_spectrum=shared_spectrum)
            else:
                raise InvalidCellType("Only cell type available for cloud RAN at the moment is 'NRCELL'!"
                                      "If you need other cell types to be implemented, please contact the author.")

        else:
            raise InvalidRan("RAN must be either cloud or classical!")

    @staticmethod
    def _is_lte_iot_cell(cell_distname, connection):
        cell_parameters = admin().get_cell_specific_info(cell_id=cell_distname, connection=connection)

        if cell_parameters.get("technology", "") == "NB-IoT-FDD":
            return True
        return False
